        """Rotate a point around the building center by current rotation."""
        if self.rotation == 0:
            return (px, py)
        w, h = self._get_display_size()
        # Center of building in scene coordinates
        cx, cy = self.x + w / 2, self.y + h / 2
        # Translate to origin
        dx, dy = px - cx, py - cy
        # Rotate
        rad = math.radians(self.rotation)
